CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_own ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES (NEW.id,left(coalesce(NEW.raw_user_meta_data->>'full_name',NEW.raw_user_meta_data->>'name',''),200)); RETURN NEW; END; $$;
CREATE TRIGGER create_user_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();
CREATE TABLE public.generations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, product_name text NOT NULL, generation_type text NOT NULL DEFAULT 'product_description', category text NOT NULL DEFAULT '', language text NOT NULL, tone text NOT NULL, content jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, DELETE ON public.generations TO authenticated;
GRANT ALL ON public.generations TO service_role;
ALTER TABLE public.generations ENABLE ROW LEVEL SECURITY;
CREATE POLICY generations_read_own ON public.generations FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY generations_delete_own ON public.generations FOR DELETE TO authenticated USING (user_id=auth.uid());
CREATE INDEX generations_user_created ON public.generations(user_id,created_at DESC);
CREATE TABLE public.generation_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, usage_day date NOT NULL DEFAULT ((now() AT TIME ZONE 'UTC')::date), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','succeeded','failed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.generation_requests TO service_role;
ALTER TABLE public.generation_requests ENABLE ROW LEVEL SECURITY;
CREATE INDEX generation_requests_user_day ON public.generation_requests(user_id,usage_day);
CREATE FUNCTION public.generation_quota() RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT greatest(0,5-count(*)::integer) FROM public.generation_requests WHERE user_id=auth.uid() AND usage_day=(now() AT TIME ZONE 'UTC')::date AND (status='succeeded' OR (status='pending' AND created_at>now()-interval '15 minutes')); $$;
REVOKE ALL ON FUNCTION public.generation_quota() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.generation_quota() TO authenticated;
CREATE FUNCTION public.reserve_generation(p_user_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; v_day date:=(now() AT TIME ZONE 'UTC')::date; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text,0)); UPDATE public.generation_requests SET status='failed' WHERE user_id=p_user_id AND status='pending' AND created_at<=now()-interval '15 minutes'; IF (SELECT count(*) FROM public.generation_requests WHERE user_id=p_user_id AND usage_day=v_day AND status='succeeded')>=5 THEN RAISE EXCEPTION 'DAILY_LIMIT'; END IF; IF EXISTS(SELECT 1 FROM public.generation_requests WHERE user_id=p_user_id AND status='pending') THEN RAISE EXCEPTION 'GENERATION_BUSY'; END IF; INSERT INTO public.generation_requests(user_id,usage_day) VALUES(p_user_id,v_day) RETURNING id INTO v_id; RETURN v_id; END; $$;
REVOKE ALL ON FUNCTION public.reserve_generation(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reserve_generation(uuid) TO service_role;
CREATE FUNCTION public.finish_generation(p_request_id uuid,p_user_id uuid,p_product_name text,p_category text,p_language text,p_tone text,p_content jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_request public.generation_requests; v_id uuid; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text,0)); SELECT * INTO v_request FROM public.generation_requests WHERE id=p_request_id AND user_id=p_user_id AND status='pending' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_RESERVATION'; END IF; IF (SELECT count(*) FROM public.generation_requests WHERE user_id=p_user_id AND usage_day=v_request.usage_day AND status='succeeded')>=5 THEN RAISE EXCEPTION 'DAILY_LIMIT'; END IF; INSERT INTO public.generations(user_id,product_name,category,language,tone,content) VALUES(p_user_id,p_product_name,p_category,p_language,p_tone,p_content) RETURNING id INTO v_id; UPDATE public.generation_requests SET status='succeeded' WHERE id=p_request_id; RETURN v_id; END; $$;
REVOKE ALL ON FUNCTION public.finish_generation(uuid,uuid,text,text,text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.finish_generation(uuid,uuid,text,text,text,text,jsonb) TO service_role;